import { createContext, useContext, useEffect, useMemo, useState, useRef, type CSSProperties, type FormEvent, type ReactNode } from 'react'
import { Link, Navigate, NavLink, Outlet, Route, Routes, useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom'
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { Activity, ArrowDownRight, ArrowLeft, ArrowRight, Award, BarChart3, Bell, BookOpen, Bookmark, Check, CheckCircle2, ChevronDown, ChevronRight, CircleHelp, Clock3, Code2, Download, ExternalLink, Filter, Flame, FolderKanban, Grid2X2, Languages, LayoutDashboard, List, Menu, Moon, MoreHorizontal, Plus, RotateCcw, Search, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Sun, Target, UserRound, Users, X } from 'lucide-react'
import { courses, initialProjects, initialStudents, levelOrder, skillCategories } from './data/seed'
import { AcademicPerformancePanel, CourseTopStudents, StudentRankingPage } from './components/Ranking'
import { translate, type Language } from './i18n'
import type { Course, Project, Proficiency, SkillEvidence, Student, StudentStatus } from './types'

type RoleMode = 'admin' | 'student' | 'guest'
type HubState = { students: Student[]; setStudents: (v: Student[]) => void; projects: Project[]; setProjects: (v: Project[]) => void; query: string; setQuery: (v: string) => void; language: Language; setLanguage: (v: Language) => void; theme: 'light' | 'dark'; setTheme: (v: 'light' | 'dark') => void; roleMode: RoleMode; setRoleMode: (v: RoleMode) => void; isAdmin: boolean; shortlistedIds: string[]; toggleShortlist: (id: string) => void; t: (value: string) => string; notify: (v: string) => void; reset: () => void }
const ACADEMIC_DATA_VERSION = '2026-11-r4'
const HubContext = createContext<HubState | null>(null)
function tx(value: string) { return translate(document.documentElement.lang === 'hy' ? 'hy' : 'en', value) }
function txCount(count: number, singular: string, plural: string) { return tx(document.documentElement.lang === 'hy' || count === 1 ? singular : plural) }
const useHub = () => {
  const value = useContext(HubContext)
  if (!value) throw new Error('HubContext is missing')
  return value
}

function App() {
  const [students, setStudents] = useState<Student[]>(loadStudents)
  const [projects, setProjects] = useState<Project[]>(loadProjects)
  const [query, setQuery] = useState('')
  const [language, setLanguage] = useState<Language>(() => localStorage.getItem('talent-hub-language') === 'hy' ? 'hy' : 'en')
  const [theme, setTheme] = useState<'light' | 'dark'>(() => localStorage.getItem('talent-hub-theme') === 'dark' ? 'dark' : 'light')
  const [roleMode, setRoleMode] = useState<RoleMode>(() => { const saved = localStorage.getItem('talent-hub-demo-role'); return saved === 'admin' || saved === 'student' ? saved : 'guest' })
  const isAdmin = roleMode === 'admin'
  const [shortlistedIds, setShortlistedIds] = useState<string[]>(() => readStorage('talent-hub-shortlist', []))
  document.documentElement.lang = language
  const [toast, setToast] = useState('')
  const t = (value: string) => translate(language, value)
  useEffect(() => { localStorage.setItem('talent-hub-language', language); document.documentElement.lang = language }, [language])
  useEffect(() => { localStorage.setItem('talent-hub-theme', theme); document.documentElement.dataset.theme = theme }, [theme])
  useEffect(() => { localStorage.setItem('talent-hub-demo-role', roleMode) }, [roleMode])
  useEffect(() => { localStorage.setItem('talent-hub-shortlist', JSON.stringify(shortlistedIds)) }, [shortlistedIds])
  useEffect(() => { localStorage.setItem('talent-hub-students', JSON.stringify(students)); localStorage.setItem('talent-hub-academic-version', ACADEMIC_DATA_VERSION) }, [students])
  useEffect(() => { localStorage.setItem('talent-hub-projects', JSON.stringify(projects)) }, [projects])
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 3000) }
  const toggleShortlist = (id: string) => setShortlistedIds(current => current.includes(id) ? current.filter(item => item !== id) : [...current, id])
  const reset = () => { setStudents(initialStudents); setProjects(initialProjects); setShortlistedIds([]); localStorage.removeItem('talent-hub-students'); localStorage.removeItem('talent-hub-projects'); localStorage.removeItem('talent-hub-shortlist'); notify('Demo data restored to the original seed.') }
  const value = { students, setStudents, projects, setProjects, query, setQuery, language, setLanguage, theme, setTheme, roleMode, setRoleMode, isAdmin, shortlistedIds, toggleShortlist, t, notify, reset }
  return <HubContext.Provider value={value}><Routes><Route element={<Shell />}><Route index element={<HomePage />} /><Route path="students" element={<StudentsPage />} /><Route path="students/:id" element={<StudentProfile />} /><Route path="courses" element={<CoursesRoute />} /><Route path="courses/:id" element={<CourseDetailRoute />} /><Route path="ranking" element={<StudentRankingPage useHub={useHub} Avatar={Avatar} t={tx} />} /><Route path="skills" element={<AdminOrGuest><SkillsPage /></AdminOrGuest>} /><Route path="projects" element={<ProjectsPage />} /><Route path="talent" element={<TalentPage />} /><Route path="analytics" element={<AdminOrGuest><AnalyticsPage /></AdminOrGuest>} /><Route path="*" element={<NotFound />} /></Route></Routes>{toast && <div className="toast"><CheckCircle2 size={16} />{toast}</div>}</HubContext.Provider>
}

function AdminOrGuest({ children }: { children: ReactNode }) {
  const { roleMode } = useHub()
  return roleMode !== 'student' ? <>{children}</> : <Navigate to="/" replace />
}

function CoursesRoute() {
  const { roleMode, students } = useHub()
  return roleMode !== 'student' ? <CoursesPage /> : <Navigate to={`/courses/${demoStudent(students).courseId}`} replace />
}

function CourseDetailRoute() {
  const { roleMode, students } = useHub()
  const { id } = useParams()
  const student = demoStudent(students)
  return roleMode !== 'student' || id === student.courseId ? <CourseDetail /> : <Navigate to={`/courses/${student.courseId}`} replace />
}

function readStorage<T>(key: string, fallback: T): T {
  try { const saved = localStorage.getItem(key); return saved ? JSON.parse(saved) as T : fallback } catch { return fallback }
}

function loadStudents(): Student[] {
  const saved = readStorage<Student[] | null>('talent-hub-students', null)
  if (!saved) return initialStudents
  const preservePerformance = localStorage.getItem('talent-hub-academic-version') === ACADEMIC_DATA_VERSION
  const byId = new Map(saved.map(student => [student.id, student]))
  return initialStudents.map(seed => { const previous = byId.get(seed.id); const savedPerformance = preservePerformance ? previous?.academicPerformance : undefined; return previous ? { ...seed, ...previous, photoUrl: seed.name === 'Arman Manukyan' ? seed.photoUrl : previous.photoUrl, academicPerformance: savedPerformance ? { ...seed.academicPerformance, ...savedPerformance, upcomingAssessments: savedPerformance.upcomingAssessments ?? seed.academicPerformance.upcomingAssessments } : seed.academicPerformance } : seed })
}

function loadProjects(): Project[] {
  const saved = readStorage<Project[] | null>('talent-hub-projects', null)
  if (!saved) return initialProjects
  const byId = new Map(saved.map(project => [project.id, project]))
  const seededIds = new Set(initialProjects.map(project => project.id))
  return [...initialProjects.map(seed => byId.get(seed.id) ?? seed), ...saved.filter(project => !seededIds.has(project.id))]
}

const navItems = [
  { label: 'Overview', to: '/', icon: LayoutDashboard }, { label: 'Students', to: '/students', icon: Users }, { label: 'Courses & Roadmaps', to: '/courses', icon: BookOpen },
  { label: 'Skills Explorer', to: '/skills', icon: Sparkles }, { label: 'Projects', to: '/projects', icon: FolderKanban }, { label: 'Talent Discovery', to: '/talent', icon: Target }, { label: 'Student Ranking', to: '/ranking', icon: Award }, { label: 'Analytics', to: '/analytics', icon: BarChart3 },
]

function Shell() {
  const { students, query, setQuery, reset, notify, language, setLanguage, theme, setTheme, roleMode, setRoleMode, isAdmin, t } = useHub()
  const [mobileNav, setMobileNav] = useState(false)
  const searchInput = useRef<HTMLInputElement>(null)
  useEffect(() => { const onKeyDown = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); searchInput.current?.focus() } }; window.addEventListener('keydown', onKeyDown); return () => window.removeEventListener('keydown', onKeyDown) }, [])
  const [showSearch, setShowSearch] = useState(false)
  const [showMenu, setShowMenu] = useState(false)
  const navigate = useNavigate()
  const location = useLocation()
  const studentViewer = demoStudent(students)
  const suggestions = useMemo(() => query.trim() ? students.filter(s => s.name.toLowerCase().includes(query.toLowerCase())).slice(0, 5) : [], [query, students])
  const visibleNavItems = roleMode !== 'student' ? navItems : [
    { label: 'Overview', to: '/', icon: LayoutDashboard },
    { label: 'My profile', to: `/students/${studentViewer.id}`, icon: UserRound },
    { label: 'Students', to: '/students', icon: Users },
    { label: 'Courses & Roadmaps', to: `/courses/${studentViewer.courseId}`, icon: BookOpen },
    { label: 'Projects', to: '/projects', icon: FolderKanban },
    { label: 'Talent Discovery', to: '/talent', icon: Target },
    { label: 'Student Ranking', to: '/ranking', icon: Award },
  ]
  const current = visibleNavItems.find(item => item.to === location.pathname) ?? visibleNavItems.find(item => location.pathname.startsWith(item.to) && item.to !== '/')
  const selectRole = (nextMode: RoleMode) => {
    setRoleMode(nextMode)
    navigate('/')
    setShowMenu(false)
    notify(nextMode === 'admin' ? 'Admin view enabled. Demo editing tools are available.' : nextMode === 'student' ? 'Student view enabled. This workspace is read-only.' : 'Guest organization view enabled. Browse and shortlist learners.')
  }
  const switchRole = () => selectRole(roleMode === 'admin' ? 'student' : roleMode === 'student' ? 'guest' : 'admin')
  const doSearch = (e: FormEvent) => { e.preventDefault(); navigate('/students'); setShowSearch(false) }
  return <div className="app-frame">
    {mobileNav && <button className="mobile-scrim" aria-label="Close navigation" onClick={() => setMobileNav(false)} />}
    <aside className={`sidebar ${mobileNav ? 'open' : ''}`}>
      <div className="brand"><div className="brand-mark"><span>t</span></div><div className="brand-copy"><strong>Talent Hub</strong><small>{t('Student discovery workspace')}</small></div><button className="icon-btn sidebar-close" onClick={() => setMobileNav(false)} aria-label="Close sidebar"><X size={18}/></button></div>
      <div className="workspace-pill"><span className="workspace-avatar">TH</span><div><strong>{t('Talent Hub')}</strong><small>{t('Demo organization')}</small></div><ChevronDown size={14}/></div>
      <div className="nav-caption">{t('WORKSPACE')}</div>
      <nav className="side-nav">{visibleNavItems.map(item => { const Icon = item.icon; return <NavLink key={item.to} to={item.to} end={item.to === '/'} onClick={() => setMobileNav(false)} className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`}><Icon size={18}/><span>{t(item.label)}</span>{item.label === 'Talent Discovery' && <span className="nav-new">{language==='hy'?'ՆՈՐ':'NEW'}</span>}</NavLink> })}</nav>
      <div className="sidebar-spacer" />
      <div className="sidebar-help"><div className="help-icon"><CircleHelp size={17}/></div><strong>{t(roleMode === 'admin' ? 'Need a hand?' : roleMode === 'guest' ? 'For your organization' : 'Your learning space')}</strong><p>{t(roleMode === 'admin' ? 'Explore the demo data and discover the hub.' : roleMode === 'guest' ? 'Find emerging talent and save promising learner profiles.' : 'Track your progress and keep building your portfolio.')}</p><button onClick={() => navigate(roleMode === 'student' ? `/students/${studentViewer.id}` : '/talent')}>{t(roleMode === 'student' ? 'Open my profile' : 'Explore talent')} <ArrowRight size={14}/></button></div>
      <div className="sidebar-user">{isAdmin ? <div className="user-avatar">AM</div> : <Avatar student={studentViewer} size="sm"/>}<div className="user-copy"><strong>{t(roleMode === 'admin' ? 'Talent Hub Manager' : roleMode === 'guest' ? 'Organization guest' : studentViewer.name)}</strong><small>{t(roleMode === 'admin' ? 'Demo admin' : roleMode === 'guest' ? 'Guest viewer' : 'Student preview')}</small></div>{isAdmin && <button className="icon-btn" onClick={reset} title={t('Reset demo data')} aria-label={t('Reset demo data')}><RotateCcw size={16}/></button>}<button className="icon-btn" onClick={() => setShowMenu(!showMenu)} aria-label={language==='hy'?'Լրացուցիչ գործողություններ':'More account actions'}><MoreHorizontal size={18}/></button>{showMenu && <div className="menu-popover user-menu">{isAdmin && <button onClick={() => { reset(); setShowMenu(false) }}><RotateCcw size={15}/>{t('Reset demo data')}</button>}{isAdmin && <button onClick={() => { navigate('/analytics'); setShowMenu(false) }}><Settings2 size={15}/>{t('Workspace analytics')}</button>}{(['admin','student','guest'] as RoleMode[]).map(mode => <button key={mode} disabled={mode === roleMode} onClick={() => selectRole(mode)}><UserRound size={15}/>{t(mode === 'admin' ? 'Admin view' : mode === 'student' ? 'Student view' : 'Guest viewer')}</button>)}</div>}</div>
    </aside>
    <main className="main-shell">
      <header className="topbar"><button className="icon-btn mobile-menu" onClick={() => setMobileNav(true)} aria-label={language==='hy'?'Բացել նավիգացիան':'Open navigation'}><Menu size={21}/></button><div className="breadcrumbs"><span>{t('Workspace')}</span><ChevronRight size={14}/><strong>{t(current?.label ?? 'Profile')}</strong></div>
        <div className="top-actions"><div className={`global-search ${showSearch ? 'focused' : ''}`}><Search size={17}/><form onSubmit={doSearch}><input ref={searchInput} value={query} onChange={e => setQuery(e.target.value)} onFocus={() => setShowSearch(true)} onBlur={() => window.setTimeout(() => setShowSearch(false), 140)} placeholder={t('Search students, skills, projects...')} aria-label={t('Search the hub')}/><kbd>⌘ K</kbd></form>{showSearch && suggestions.length > 0 && <div className="search-results">{suggestions.map(s => <button key={s.id} onMouseDown={() => { navigate(`/students/${s.id}`); setQuery('') }}><Avatar student={s} size="sm"/><span><strong>{s.name}</strong><small>{courseName(s.courseId)}</small></span><ArrowRight size={14}/></button>)}<button className="search-all" onMouseDown={() => navigate('/students')}>{t('View all matching students')} <ArrowRight size={14}/></button></div>}</div><button className="icon-btn theme-toggle" onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')} title={t(theme === 'light' ? 'Switch to dark mode' : 'Switch to light mode')} aria-label={t(theme === 'light' ? 'Switch to dark mode' : 'Switch to light mode')}>{theme === 'light' ? <Moon size={17}/> : <Sun size={17}/>}</button><label className="language-control" title={language==='hy'?'Փոխել լեզուն':'Change language'}><Languages size={15}/><span className="sr-only">{language==='hy'?'Լեզու':'Language'}</span><select value={language} onChange={e=>setLanguage(e.target.value as Language)} aria-label={language==='hy'?'Լեզու':'Language'}><option value="en">EN</option><option value="hy">ՀԱՅ</option></select></label><span className="environment-chip"><i/>{t('Demo environment')}</span><button className={`role-switch ${roleMode === 'admin' ? 'is-admin' : roleMode === 'guest' ? 'is-guest' : 'is-student'}`} onClick={switchRole} title={t('Cycle view modes')}><span className="role-switch-icon">{roleMode === 'admin' ? <ShieldCheck size={13}/> : roleMode === 'guest' ? <Users size={13}/> : <UserRound size={13}/>}</span>{t(roleMode === 'admin' ? 'Admin view' : roleMode === 'student' ? 'Student view' : 'Guest view')}</button><button className="icon-btn notification" title={language==='hy'?'Ծանուցումներ':'Notifications'} aria-label={language==='hy'?'Ծանուցումներ':'Notifications'} onClick={()=>notify(language==='hy'?'Նոր դեմո ծանուցումներ չկան։':'You’re all caught up. No new demo notifications.')}><Bell size={18}/><i/></button>{isAdmin ? <div className="top-user">AM</div> : <Avatar student={studentViewer} size="sm"/>}</div>
      </header>
      <div className={`demo-banner ${roleMode !== 'admin' ? 'read-only-banner' : ''}`}><ShieldCheck size={14}/><span>{t(roleMode === 'admin' ? 'DEMO ENVIRONMENT — All student profiles, projects, skills, and statistics are fictional and created for product demonstration purposes.' : roleMode === 'guest' ? 'GUEST ORGANIZATION VIEW — Browse fictional student profiles, discover talent, and save a shortlist. Student data is read-only.' : 'STUDENT PREVIEW — This is a read-only view of a fictional demo learner profile.')}</span>{isAdmin ? <button onClick={reset}>{t('Reset data')} <RotateCcw size={12}/></button> : <span className="read-only-chip">{t('Read only')}</span>}</div>
      <div className="page-container"><Outlet /></div>
      <footer className="app-footer"><span>© 2026 Talent Hub Demo</span><span>{t('Independent concept · Not an official system')}</span></footer>
    </main>
  </div>
}

function PageHeading({ eyebrow, title, description, actions }: { eyebrow?: string; title: string; description: string; actions?: ReactNode }) {
  const { t } = useHub()
  return <div className="page-heading"><div><div className="eyebrow">{eyebrow && t(eyebrow)}</div><h1>{t(title)}</h1><p>{t(description)}</p></div>{actions && <div className="heading-actions">{actions}</div>}</div>
}

function Avatar({ student, size = 'md' }: { student: Student; size?: 'sm' | 'md' | 'lg' }) {
  const colors = ['#ede4ff','#e0f3ff','#fee9df','#e3f3e9','#ffe6f1','#e9ecff']
  const colorIndex = Number(student.id.replace('s','')) % colors.length
  const initials = student.name.split(' ').map(part => part[0]).slice(0,2).join('')
  return <div className={`avatar avatar-${size} ${student.photoUrl ? 'avatar-with-photo' : ''}`} style={{ background: colors[colorIndex] }}><span className="avatar-fallback">{initials}</span>{student.photoUrl && <img src={student.photoUrl} alt="" loading="lazy" referrerPolicy="no-referrer" onError={event=>event.currentTarget.remove()}/>}</div>
}

function demoStudent(students: Student[]) { return students.find(student => student.name === 'Arman Manukyan') ?? students[0] }
function skillNamesFor(students: Student[]) { return Array.from(new Set(students.flatMap(student => student.skills.map(skill => skill.name)))).sort() }
function courseName(id: string) { return courses.find(c => c.id === id)?.title ?? id }
function courseFor(id: string) { return courses.find(c => c.id === id) ?? courses[0] }
function projectCount(studentId: string, projects: Project[]) { return projects.filter(p => p.studentId === studentId && p.status === 'Completed').length }
function readinessScore(student: Student) { const r = student.readiness; return Math.round((r.technical + r.projects + r.problemSolving + r.portfolio) / 4) }
function ProgressBar({ value, color = 'violet' }: { value: number; color?: string }) { return <div className={`progress-track ${color}`}><span style={{ width: `${Math.max(0, Math.min(100, value))}%` }}/></div> }
function StatusPill({ status }: { status: StudentStatus | Project['status'] }) { const {t}=useHub();const c = status.toLowerCase().replaceAll(' ', '-'); return <span className={`status-pill status-${c}`}><i/>{t(status)}</span> }
function MetricCard({ label, value, delta, icon: Icon, tone = 'violet', foot }: { label: string; value: string | number; delta?: string; icon: typeof Users; tone?: string; foot?: string }) { const {t}=useHub();return <div className="metric-card"><div className={`metric-icon ${tone}`}><Icon size={18}/></div><div className="metric-label">{t(label)}<span className="tip" title={t(foot ?? label)}>i</span></div><div className="metric-value">{value}</div><div className="metric-foot">{delta ? <span className="metric-delta"><ArrowDownRight size={13}/>{t(delta)}</span> : <span className="metric-muted">{t('Live from demo dataset')}</span>}{foot && <span className="metric-note">{t(foot)}</span>}</div></div> }

function HomePage() { const { roleMode } = useHub(); return roleMode === 'student' ? <StudentDashboard /> : <Dashboard /> }

function StudentDashboard() {
  const { students, projects } = useHub()
  const student = demoStudent(students)
  if (!student) return <NotFound />
  const course = courseFor(student.courseId)
  const ownProjects = projects.filter(project => project.studentId === student.id).sort((a,b)=>b.completedAt.localeCompare(a.completedAt))
  const currentPhaseIndex = Math.min(course.phases.length - 1, Math.floor(student.progress / (100 / course.phases.length)))
  const currentPhase = course.phases[currentPhaseIndex]
  const completedModules = Math.round(course.phases.reduce((sum,phase)=>sum+phase.modules.length,0)*student.progress/100)
  const totalModules = course.phases.reduce((sum,phase)=>sum+phase.modules.length,0)
  return <>
    <PageHeading eyebrow="MY LEARNING SPACE" title={`${tx('Welcome back')}, ${student.name.split(' ')[0]}`} description="Your learning path, portfolio, and next milestone in one place." actions={<Link className="btn btn-secondary" to={`/students/${student.id}`}>{tx('Open my profile')} <ArrowRight size={15}/></Link>} />
    <section className="student-welcome-card">
      <div className="student-welcome-main">
        <div className="student-welcome-identity"><Avatar student={student} size="lg"/><div><span className="student-welcome-overline">{tx('YOUR LEARNING PATH')}</span><h2>{course.title}</h2><p>{course.track}</p></div><StatusPill status={student.status}/></div>
        <div className="student-welcome-progress"><div className="student-progress-ring" style={{'--progress-angle': `${student.progress * 3.6}deg`} as CSSProperties}><div><strong>{student.progress}%</strong><span>{tx('complete')}</span></div></div><div className="student-progress-copy"><span>{tx('ROADMAP PROGRESS')}</span><h3>{tx(student.stage)}</h3><ProgressBar value={student.progress}/><small>{completedModules} / {totalModules} {tx('modules completed')}</small></div></div>
      </div>
      <aside className="student-next-step"><span className="student-next-label"><Sparkles size={14}/>{tx('YOUR NEXT MILESTONE')}</span><h3>{currentPhase.modules[0]?.name ?? tx('Final project')}</h3><p>{tx('Keep moving through your roadmap at your own pace. Your progress is saved in this demo workspace.')}</p><Link to={`/courses/${course.id}`} className="student-next-link">{tx('Open my roadmap')} <ArrowRight size={15}/></Link></aside>
      <div className="student-welcome-glow"/>
    </section>
    <section className="student-home-stat-grid"><MetricCard label="Completed projects" value={ownProjects.filter(project=>project.status==='Completed').length} delta={`${ownProjects.length} ${tx('portfolio projects')}`} icon={FolderKanban} tone="green"/><MetricCard label="Technical skills" value={student.skills.length} delta={tx('In your profile')} icon={Sparkles} tone="violet"/><MetricCard label="Modules completed" value={`${completedModules}/${totalModules}`} delta={tx('Across your learning path')} icon={CheckCircle2} tone="blue"/></section>
    <div className="student-home-grid"><section className="panel student-home-roadmap"><div className="panel-heading"><div><h2>{tx('Your roadmap')}</h2><p>{tx('A quick look at what you have completed and what comes next.')}</p></div><Link className="text-link" to={`/courses/${course.id}`}>{tx('View course')} <ArrowRight size={14}/></Link></div><div className="journey-list">{course.phases.map((phase,index)=>{const threshold=Math.round((index+1)/course.phases.length*100);const done=student.progress>=threshold;const current=!done&&student.progress>Math.round(index/course.phases.length*100);return <div className={`journey-row ${done?'done':''} ${current?'current':''}`} key={phase.name}><span className="journey-marker">{done?<Check size={13}/>:String(index+1).padStart(2,'0')}</span><div className="journey-content"><div><strong>{tx(phase.name.replace(/^\d+ · /,''))}</strong><span>{tx(done?'Completed':current?'In progress':'Upcoming')}</span></div><small>{phase.modules.map(module=>module.name).join(' · ')}</small></div><span className="journey-status">{done?'✓':current?<Clock3 size={15}/>:''}</span></div>})}</div></section>
      <section className="panel student-home-skills"><div className="panel-heading"><div><h2>{tx('Skills you are building')}</h2><p>{tx('Your latest skill evidence')}</p></div><Link className="text-link" to={`/students/${student.id}`}>{tx('See profile')} <ArrowRight size={14}/></Link></div><div className="profile-skill-list">{student.skills.slice(0,4).map(skill=><SkillEvidenceRow key={skill.name} item={skill}/>)}</div></section>
      <section className="panel student-home-projects"><div className="panel-heading"><div><h2>{tx('Recent projects')}</h2><p>{tx('Your portfolio work')}</p></div><Link className="text-link" to={`/students/${student.id}`}>{tx('Open portfolio')} <ArrowRight size={14}/></Link></div>{ownProjects.length?<div className="student-project-list">{ownProjects.slice(0,3).map(project=><div className="student-project-row" key={project.id}><span className="student-project-icon"><FolderKanban size={15}/></span><span><strong>{project.title}</strong><small>{project.technologies.slice(0,3).join(' · ')}</small></span><StatusPill status={project.status}/></div>)}</div>:<div className="compact-empty">{tx('Your project portfolio is ready for your first demo project.')}</div>}</section></div>
  </>
}

function Dashboard() {
  const { students, projects } = useHub()
  const completed = projects.filter(p => p.status === 'Completed').length
  const active = students.filter(s => s.status === 'Active').length
  const graduates = students.filter(s => s.status === 'Graduated').length
  const avgProgress = Math.round(students.reduce((sum,s) => sum+s.progress,0) / Math.max(1,students.length))
  const ready = students.filter(s => readinessScore(s) >= 70 && projectCount(s.id,projects) >= 2).length
  const topSkillStats = skillNamesFor(students).map(name => ({ name, count: students.filter(s => s.skills.some(skill => skill.name === name)).length })).sort((a,b) => b.count-a.count).slice(0,6)
  const courseData = courses.map(c => ({ name: c.title.replace('Modern AI Software Developer','Modern AI Dev').replace('AI Application Development','AI App Dev'), students: students.filter(s => s.courseId === c.id).length, fill: c.colors[0] }))
  const stageData = [{ name:'Foundation', value:students.filter(s=>s.progress<35).length, color:'#d9d1fb' },{ name:'Building', value:students.filter(s=>s.progress>=35&&s.progress<70).length, color:'#a690ef' },{ name:'Advanced', value:students.filter(s=>s.progress>=70&&s.progress<100).length, color:'#704be0' },{ name:'Completed', value:graduates, color:'#31205f' }]
  const top = [...students].sort((a,b)=>readinessScore(b)-readinessScore(a)).slice(0,4)
  const recent = [...projects].filter(p=>p.status==='Completed').sort((a,b)=>b.completedAt.localeCompare(a.completedAt)).slice(0,4)
  return <>
    <PageHeading eyebrow="THURSDAY, NOVEMBER 19, 2026" title="Talent overview" description="A clear view of learner growth, practical work, and emerging talent." actions={<><Link className="btn btn-secondary" to="/analytics"><BarChart3 size={16}/>{tx("View analytics")}</Link><Link className="btn btn-primary" to="/talent"><Sparkles size={16}/>{tx("Discover talent")}</Link></>} />
    <section className="metric-grid metric-grid-4">
      <MetricCard label="Total students" value={students.length} delta="Across 8 learning paths" icon={Users} tone="violet" />
      <MetricCard label="Active learners" value={active} delta="Currently enrolled" icon={Activity} tone="blue" />
      <MetricCard label="Graduates" value={graduates} delta="Completed demo roadmaps" icon={Award} tone="green" />
      <MetricCard label="In progress" value={students.filter(s=>s.progress>0&&s.progress<100&&s.status==='Active').length} delta="Moving through a course" icon={BookOpen} tone="orange" />
      <MetricCard label="Average progress" value={`${avgProgress}%`} delta="Across all roadmaps" icon={Target} tone="orange" />
      <MetricCard label="Completed projects" value={completed} delta={`${projects.length} ${tx('total project records')}`}  icon={FolderKanban} tone="green" />
      <MetricCard label="Technical skills" value={skillNamesFor(students).length} delta="Distinct skills in profiles" icon={Sparkles} tone="violet" />
      <MetricCard label="Ready for portfolio review" value={ready} delta="Demo readiness ≥ 70" icon={Flame} tone="blue" />
    </section>
    <div className="dashboard-main-grid">
      <section className="panel course-chart-panel"><div className="panel-heading"><div><h2>{tx("Student distribution")}</h2><p>{tx("Learners across public Academy programs")}</p></div><Link to="/courses" className="text-link">{tx("All courses")} <ArrowRight size={14}/></Link></div><div className="chart-wrap course-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={courseData} layout="vertical" margin={{ top: 0, right: 22, left: 4, bottom: 0 }} barSize={13}><CartesianGrid horizontal={false} stroke="#f0eef4"/><XAxis type="number" allowDecimals={false} axisLine={false} tickLine={false} tick={{ fill:'#9994a3',fontSize:11 }} /><YAxis type="category" dataKey="name" width={150} axisLine={false} tickLine={false} tick={{ fill:'#666171',fontSize:11 }} /><Tooltip cursor={{fill:'#f8f6fc'}} contentStyle={{border:'1px solid #eeeaf3',borderRadius:12,boxShadow:'0 8px 22px #33215412'}}/><Bar dataKey="students" name="Students" radius={[0,6,6,0]}>{courseData.map((entry,index)=><Cell key={index} fill={entry.fill}/>)}</Bar></BarChart></ResponsiveContainer></div><div className="chart-legend"><span><i className="legend-dot violet-dot"/>{tx("Students per learning path")}</span><span className="chart-total">{students.length} {tx("total")}</span></div></section>
      <section className="panel stage-panel"><div className="panel-heading"><div><h2>{tx("Learning stage")}</h2><p>{tx("Progress across all learners")}</p></div><button className="icon-btn" title={tx("Stage counts use current progress")}><MoreHorizontal size={18}/></button></div><div className="stage-chart-wrap"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={stageData} dataKey="value" nameKey="name" cx="50%" cy="50%" innerRadius={68} outerRadius={92} paddingAngle={3} stroke="none">{stageData.map((entry,index)=><Cell key={index} fill={entry.color}/>)}</Pie><Tooltip contentStyle={{border:'1px solid #eeeaf3',borderRadius:12}}/></PieChart></ResponsiveContainer><div className="donut-center"><strong>{avgProgress}%</strong><span>{tx("AVG. PROGRESS")}</span></div></div><div className="stage-legend">{stageData.map(d=><div key={d.name}><span><i style={{background:d.color}}/>{tx(d.name)}</span><b>{d.value}</b></div>)}</div></section>
    </div>
    <div className="dashboard-lower-grid">
      <section className="panel student-table-panel"><div className="panel-heading"><div><h2>{tx("Top portfolio readiness")}</h2><p>{tx("Demo readiness indicator · based on project and skill evidence")}</p></div><Link to="/students" className="text-link">{tx("View directory")} <ArrowRight size={14}/></Link></div><div className="table-scroll"><table className="data-table"><thead><tr><th>{tx("STUDENT")}</th><th>{tx("LEARNING PATH")}</th><th>{tx("PROGRESS")}</th><th>{tx("DEMO READINESS")}</th><th></th></tr></thead><tbody>{top.map(s=><tr key={s.id}><td><Link className="student-identity" to={`/students/${s.id}`}><Avatar student={s} size="sm"/><span><strong>{s.name}</strong><small>{tx(s.level)} {tx("learner")}</small></span></Link></td><td><span className="course-cell"><i style={{background:courseFor(s.courseId).colors[0]}}/>{courseName(s.courseId)}</span></td><td><div className="mini-progress"><ProgressBar value={s.progress}/><span>{s.progress}%</span></div></td><td><span className="readiness-value"><i/>{readinessScore(s)}%</span></td><td><Link className="row-arrow" to={`/students/${s.id}`} aria-label={`${tx("Open profile")}: ${s.name}`}><ArrowRight size={16}/></Link></td></tr>)}</tbody></table></div></section>
      <section className="panel recent-panel"><div className="panel-heading"><div><h2>{tx("Recent project reviews")}</h2><p>{tx("Latest completed student work")}</p></div><Link to="/projects" className="text-link">{tx("Gallery")} <ArrowRight size={14}/></Link></div><div className="recent-list">{recent.map(p=>{const s=students.find(x=>x.id===p.studentId)!; return <Link key={p.id} to={`/students/${s.id}`} className="recent-item"><ProjectArt project={p}/><div className="recent-copy"><strong>{p.title}</strong><span>{s.name} · {courseName(s.courseId)}</span></div><div className="score-tag">{p.score}<small>/100</small></div></Link>})}</div></section>
    </div>
    <div className="dashboard-bottom-grid"><section className="panel top-students-panel"><div className="panel-heading"><div><h2>{tx("Standout talent")}</h2><p>{tx("High evidence coverage across the demo cohort")}</p></div><Link to="/talent" className="text-link">{tx("Find talent")} <ArrowRight size={14}/></Link></div><div className="standout-list">{top.slice(0,3).map((s,i)=><Link to={`/students/${s.id}`} key={s.id} className="standout-item"><span className="rank">0{i+1}</span><Avatar student={s}/><div className="standout-copy"><strong>{s.name}</strong><span>{courseName(s.courseId)}</span></div><span className="skill-chip">{s.skills[0]?.name}</span><b>{readinessScore(s)}<small>%</small></b></Link>)}</div></section><section className="readiness-callout"><div className="callout-glow"/><div className="callout-icon"><Flame size={21}/></div><span className="callout-label">{tx("PORTFOLIO REVIEW QUEUE")}</span><strong>{ready} {txCount(ready,"student","Students")}</strong><p>{tx("meet the demo threshold for a portfolio review.")}</p><Link to="/talent">{tx("View matching profiles")} <ArrowRight size={14}/></Link><div className="callout-bottom"><span>{tx("Readiness is an illustrative demo signal")}</span><span>↗</span></div></section></div>
    <div className="dashboard-activity-grid"><section className="panel recent-panel"><div className="panel-heading"><div><h2>{tx("Recent learning activity")}</h2><p>{tx("Achievements and project milestones from the demo records")}</p></div><Link to="/students" className="text-link">{tx("Student directory")} <ArrowRight size={14}/></Link></div><div className="recent-list">{students.flatMap(s=>s.achievements.map(a=>({student:s,title:a.title,date:a.date,note:a.note}))).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map((a,i)=><Link key={`${a.student.id}-${i}`} to={`/students/${a.student.id}`} className="activity-row"><span className="activity-marker"><Award size={13}/></span><span className="activity-copy"><strong>{a.student.name} <small>{a.title.toLowerCase()}</small></strong><span>{a.note}</span></span><time>{formatDate(a.date)}</time></Link>)}</div></section><section className="panel dashboard-skills-panel"><div className="panel-heading"><div><h2>{tx("Skill distribution")}</h2><p>{tx("Most represented capabilities")}</p></div><Link to="/skills" className="text-link">{tx("Explore")} <ArrowRight size={13}/></Link></div><div className="dashboard-skill-bars">{topSkillStats.map(skill=><div key={skill.name}><span>{skill.name}</span><div><i style={{width:`${skill.count/Math.max(...topSkillStats.map(x=>x.count),1)*100}%`}}/></div><b>{skill.count}</b></div>)}</div></section><section className="panel recent-panel graduate-panel"><div className="panel-heading"><div><h2>{tx("Recently completed paths")}</h2><p>{tx("Students with completed roadmaps")}</p></div><span className="graduation-count">{graduates}</span></div>{students.filter(s=>s.status==='Graduated').slice(0,4).map(s=><Link to={`/students/${s.id}`} key={s.id} className="recent-graduate"><span className="graduate-check"><Check size={13}/></span><span><strong>{s.name}</strong><small>{courseName(s.courseId)} · {tx("Completed")} {formatDate(s.achievements.find(a=>a.kind==='Certificate')?.date??s.enrolledAt)}</small></span><ArrowRight size={14}/></Link>)}</section></div>
  </>
}

function StudentsPage() {
  const { students, projects, query, setQuery } = useHub()
  const [searchParams, setSearchParams] = useSearchParams(); const [course, setCourse] = useState(searchParams.get('course') ?? 'all'); const [skill, setSkill] = useState(searchParams.get('skill') ?? 'all'); const [level, setLevel] = useState('all'); const [status, setStatus] = useState('all'); const [progress, setProgress] = useState('all'); const [sort, setSort] = useState('name'); const [view, setView] = useState<'grid'|'table'>('grid')
  const filtered = useMemo(() => {
    const out = students.filter(s => (!query || s.name.toLowerCase().includes(query.toLowerCase())) && (course==='all'||s.courseId===course) && (skill==='all'||s.skills.some(x=>x.name===skill)) && (level==='all'||s.level===level) && (status==='all'||s.status===status) && (progress==='all'||(progress==='near'&&s.progress>=75)||(progress==='early'&&s.progress<35)||(progress==='middle'&&s.progress>=35&&s.progress<75)))
    return out.sort((a,b)=>sort==='progress'?b.progress-a.progress:sort==='projects'?projectCount(b.id,projects)-projectCount(a.id,projects):a.name.localeCompare(b.name))
  }, [students, projects, query, course, skill, level, status, progress, sort])
  const clear = () => { setQuery('');setSearchParams({});setCourse('all');setSkill('all');setLevel('all');setStatus('all');setProgress('all');setSort('name') }
  const activeFilters = [course,skill,level,status,progress].filter(x=>x!=='all').length + (query?1:0)
  return <><PageHeading eyebrow="TALENT DIRECTORY" title="Students" description="Find a learner by name, learning path, skill, or progress." actions={<button className="btn btn-secondary" onClick={()=>window.print()}><Download size={16}/>{tx("Export view")}</button>} />
    <section className="directory-toolbar"><div className="filter-label"><SlidersHorizontal size={17}/><strong>{tx("Filters")}</strong>{activeFilters>0&&<span className="filter-count">{activeFilters}</span>}</div><div className="filter-controls"><select value={course} onChange={e=>setCourse(e.target.value)} aria-label={tx("Filter by course")}><option value="all">{tx("All learning paths")}</option>{courses.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select><select value={skill} onChange={e=>setSkill(e.target.value)} aria-label={tx("Filter by skill")}><option value="all">{tx("All skills")}</option>{skillNamesFor(students).map(x=><option key={x}>{x}</option>)}</select><select value={level} onChange={e=>setLevel(e.target.value)} aria-label={tx("Filter by level")}><option value="all">{tx("All levels")}</option>{['Foundation','Intermediate','Advanced'].map(x=><option key={x} value={x}>{tx(x)}</option>)}</select><select value={progress} onChange={e=>setProgress(e.target.value)} aria-label={tx("Filter by progress")}><option value="all">{tx("Any progress")}</option><option value="early">{tx("Early · under 35%")}</option><option value="middle">{tx("In progress · 35–74%")}</option><option value="near">{tx("Near completion · 75%+")}</option></select><select value={status} onChange={e=>setStatus(e.target.value)} aria-label={tx("Filter by status")}><option value="all">{tx("All statuses")}</option>{['Active','Graduated','Paused','At risk'].map(x=><option key={x} value={x}>{tx(x)}</option>)}</select></div><button className="clear-filters" onClick={clear} disabled={!activeFilters}>{tx("Clear all")}</button></section>
    <section className="results-bar"><div><strong>{filtered.length} {txCount(filtered.length,'student','Students')}</strong><span>{activeFilters ? ` ${tx('matching')} ${activeFilters} ${tx(activeFilters===1?'active filter':'active filters')}` : ` ${tx('in the demo cohort')}`}</span></div><div className="results-tools"><label>{tx("Sort by")} <select value={sort} onChange={e=>setSort(e.target.value)}><option value="name">{tx("Name")}</option><option value="progress">{tx("Progress")}</option><option value="projects">{tx("Projects")}</option></select></label><div className="view-toggle"><button onClick={()=>setView('grid')} className={view==='grid'?'selected':''} aria-label={tx("Grid view")}><Grid2X2 size={16}/></button><button onClick={()=>setView('table')} className={view==='table'?'selected':''} aria-label={tx("Table view")}><List size={17}/></button></div></div></section>
    {filtered.length ? view==='grid' ? <div className="student-grid">{filtered.map(s=><StudentCard key={s.id} student={s} projects={projects}/>)}</div> : <div className="panel directory-table"><div className="table-scroll"><table className="data-table"><thead><tr><th>{tx("STUDENT")}</th><th>{tx("COURSE")}</th><th>{tx("STAGE")}</th><th>{tx("SKILLS")}</th><th>{tx("PROGRESS")}</th><th>{tx("PROJECTS")}</th><th>{tx("STATUS")}</th><th></th></tr></thead><tbody>{filtered.map(s=><tr key={s.id}><td><Link className="student-identity" to={`/students/${s.id}`}><Avatar student={s} size="sm"/><span><strong>{s.name}</strong><small>{tx(s.level)}</small></span></Link></td><td>{courseName(s.courseId)}</td><td>{tx(s.stage)}</td><td><div className="inline-chips">{s.skills.slice(0,2).map(x=><span className="skill-chip" key={x.name}>{x.name}</span>)}</div></td><td><div className="mini-progress"><ProgressBar value={s.progress}/><span>{s.progress}%</span></div></td><td>{projectCount(s.id,projects)}</td><td><StatusPill status={s.status}/></td><td><Link className="row-arrow" to={`/students/${s.id}`}><ArrowRight size={16}/></Link></td></tr>)}</tbody></table></div></div> : <div className="empty-state"><div className="empty-icon"><Search size={22}/></div><h3>{tx("No students match these filters")}</h3><p>{tx("Try removing a filter or searching for a different name or skill.")}</p><button className="btn btn-secondary" onClick={clear}>{tx("Clear all filters")}</button></div>}
  </>
}

function StudentCard({ student, projects }: { student: Student; projects: Project[] }) {
  const doneCount = projectCount(student.id,projects)
  return <Link to={`/students/${student.id}`} className="student-card"><div className="student-card-top"><Avatar student={student} size="lg"/><StatusPill status={student.status}/><button className="card-more" aria-label={tx("Open student profile")}><MoreHorizontal size={18}/></button></div><div className="student-card-title"><h3>{student.name}</h3><span>{tx(student.level)} {tx("learner")}</span></div><div className="student-course"><i style={{background:courseFor(student.courseId).colors[0]}}/>{courseName(student.courseId)}</div><div className="student-card-stage"><span>{tx("Current stage")}</span><strong>{tx(student.stage)}</strong></div><div className="card-progress-label"><span>{tx("Roadmap progress")}</span><b>{student.progress}%</b></div><ProgressBar value={student.progress}/><div className="student-card-bottom"><div className="inline-chips">{student.skills.slice(0,2).map(x=><span className="skill-chip" key={x.name}>{x.name}</span>)}{student.skills.length>2&&<span className="more-chip">+{student.skills.length-2}</span>}</div><span className="project-count"><FolderKanban size={14}/>{doneCount}</span></div></Link>
}

function StudentProfile() {
  const { id = '' } = useParams(); const { students, setStudents, projects, setProjects, notify, isAdmin } = useHub(); const navigate=useNavigate(); const student=students.find(s=>s.id===id); const [tab,setTab]=useState<'overview'|'performance'|'roadmap'|'skills'|'portfolio'>('overview'); const [editing,setEditing]=useState(false); const [adding,setAdding]=useState(false)
  if (!student) return <NotFound />
  const course=courseFor(student.courseId); const studentProjects=projects.filter(p=>p.studentId===student.id); const ready=readinessScore(student)
  const saveProfile=(bio:string, progress:number, status:StudentStatus, skillNames:string[])=>{if(!isAdmin)return;const skills:SkillEvidence[]=skillNames.map(name=>student.skills.find(x=>x.name.toLowerCase()===name.toLowerCase())??{name,category:guessCategory(name),proficiency:'Developing',module:course.phases[0].modules[0].name,evidence:`Added in demo profile editor · ${course.title}`}); setStudents(students.map(s=>s.id===student.id?{...s,bio,progress,status,skills,stage:course.phases[Math.min(course.phases.length-1,Math.floor(progress/(100/course.phases.length)))].name.replace(/^\d+ · /,''),readiness:{...s.readiness,technical:Math.min(98,Math.max(22,progress)),problemSolving:Math.min(96,Math.max(25,Math.round((s.readiness.problemSolving+progress)/2)))}}:s)); setEditing(false); notify('Student profile updated and saved locally.') }
  const addProject=(title:string,description:string,technologies:string[],category:string)=>{if(!isAdmin)return;const project:Project={id:`${student.id}-custom-${Date.now()}`,studentId:student.id,title,description,technologies,category,completedAt:new Date().toISOString().slice(0,10),score:0,status:'In progress',art:'art-lilac'};setProjects([project,...projects]);setStudents(students.map(s=>s.id===student.id?{...s,readiness:{...s.readiness,projects:Math.min(100,s.readiness.projects+8),portfolio:Math.min(100,s.readiness.portfolio+8)}}:s));setAdding(false);notify('Project added to the student portfolio.')}
  return <><div className="profile-breadcrumb"><button className="back-link" onClick={()=>navigate('/students')}><ArrowLeft size={15}/>{tx('Students')}</button><ChevronRight size={14}/><span>{student.name}</span></div>
    <section className="profile-hero"><div className="profile-identity"><Avatar student={student} size="lg"/><div><div className="profile-title-row"><h1>{student.name}</h1><StatusPill status={student.status}/></div><div className="profile-meta"><Link to={`/courses/${course.id}`}><i style={{background:course.colors[0]}}/>{course.title}</Link><span>·</span><span>{tx(student.level)} {tx('learner')}</span><span>·</span><span>{tx("Joined")} {formatDate(student.enrolledAt)}</span></div><p>{student.bio}</p><div className="profile-socials"><a href={student.socialProfiles.linkedin} target="_blank" rel="noreferrer" aria-label={`${student.name} LinkedIn demo search`}><span className="linkedin-mark">in</span><span>LinkedIn<small>{tx('Demo profile search')}</small></span><ExternalLink size={12}/></a><a href={student.socialProfiles.github} target="_blank" rel="noreferrer" aria-label={`${student.name} GitHub demo search`}><Code2 size={15}/><span>GitHub<small>{tx('Demo profile search')}</small></span><ExternalLink size={12}/></a><small className="profile-social-note">{tx('Fictional demo links')}</small></div></div></div>{isAdmin&&<div className="profile-actions"><button className="btn btn-secondary" onClick={()=>setEditing(true)}><Settings2 size={16}/>{tx("Edit profile")}</button><button className="btn btn-primary" onClick={()=>setAdding(true)}><Plus size={16}/>{tx("Add project")}</button></div>}</section>
    <section className="profile-stats"><div><span>{tx("Roadmap progress")}</span><strong>{student.progress}%</strong><ProgressBar value={student.progress}/></div><div><span>{tx("Completed modules")}</span><strong>{Math.round(course.phases.reduce((a,p)=>a+p.modules.length,0)*student.progress/100)}<small> / {course.phases.reduce((a,p)=>a+p.modules.length,0)}</small></strong></div><div><span>{tx("Completed projects")}</span><strong>{studentProjects.filter(p=>p.status==='Completed').length}<small> / {studentProjects.length}</small></strong></div><div><span>{tx("Demo readiness")}</span><strong>{ready}<small> / 100</small></strong><small className="demo-eval-label">{tx("Illustrative evaluation")}</small></div></section>
    <div className="profile-tabs">{(['overview','performance','roadmap','skills','portfolio'] as const).map(t=><button key={t} className={tab===t?'active':''} onClick={()=>setTab(t)}>{tx(t==='overview'?'Overview':t==='performance'?'Academic performance':t==='roadmap'?'Learning roadmap':t==='skills'?'Skills & evidence':'Portfolio')}{t==='portfolio'&&<span>{studentProjects.length}</span>}</button>)}</div>
    {tab==='performance'&&<AcademicPerformancePanel student={student} useHub={useHub} Avatar={Avatar} t={tx}/>}
    {tab==='overview'&&<div className="profile-content-grid"><div className="profile-main-col"><section className="panel profile-section"><div className="panel-heading"><div><h2>{tx("Learning journey")}</h2><p>{tx("Roadmap progress by phase · illustrative for demo use")}</p></div><button className="text-link" onClick={()=>setTab('roadmap')}>{tx("View roadmap")} <ArrowRight size={14}/></button></div><div className="journey-list">{course.phases.map((p,i)=>{const phaseThreshold=Math.round((i+1)/course.phases.length*100);const done=student.progress>=phaseThreshold;const current=!done&&student.progress>Math.round(i/course.phases.length*100);return <div className={`journey-row ${done?'done':''} ${current?'current':''}`} key={p.name}><span className="journey-marker">{done?<Check size={13}/>:String(i+1).padStart(2,'0')}</span><div className="journey-content"><div><strong>{tx(p.name.replace(/^\d+ · /,''))}</strong><span>{tx(done?'Completed':current?'In progress':'Upcoming')}</span></div><small>{p.modules.map(m=>m.name).join(' · ')}</small></div><span className="journey-status">{done?'✓':current?<Clock3 size={15}/>:''}</span></div>})}</div></section><section className="panel profile-section"><div className="panel-heading"><div><h2>{tx("Technical skills")}</h2><p>{tx("Evidence tied to learning modules and projects")}</p></div><button className="text-link" onClick={()=>setTab('skills')}>{tx("All skills")} <ArrowRight size={14}/></button></div><div className="profile-skill-list">{student.skills.slice(0,5).map(s=><SkillEvidenceRow key={s.name} item={s}/>)}</div></section><section className="panel profile-section"><div className="panel-heading"><div><h2>{tx("Project portfolio")}</h2><p>{tx("Practical work completed during the learning path")}</p></div><button className="text-link" onClick={()=>setTab('portfolio')}>{tx("All projects")} <ArrowRight size={14}/></button></div><div className="profile-projects">{studentProjects.slice(0,2).map(p=><ProjectCard key={p.id} project={p} student={student}/>)}</div></section></div>
      <aside className="profile-side-col"><section className="panel readiness-panel"><div className="panel-heading"><div><h2>{tx("Career readiness")}</h2><p>{tx("Demo evaluation · not an official Academy assessment")}</p></div><span className="readiness-score">{ready}</span></div><div className="readiness-bars">{Object.entries({ 'Technical foundation':student.readiness.technical,'Project experience':student.readiness.projects,'Problem-solving':student.readiness.problemSolving,'Portfolio completeness':student.readiness.portfolio }).map(([label,v])=><div key={label}><div><span>{tx(label)}</span><b>{v}%</b></div><ProgressBar value={v}/></div>)}</div><div className="readiness-foot"><ShieldCheck size={15}/>{tx("Based on demo data only")}</div></section><section className="panel profile-section"><div className="panel-heading"><div><h2>{tx("Achievements")}</h2><p>{tx("Milestones and learning highlights")}</p></div></div>{student.achievements.length?<div className="achievement-list">{student.achievements.map((a,i)=><div className="achievement-row" key={`${a.title}-${i}`}><div className="achievement-icon"><Award size={16}/></div><div><strong>{a.title}</strong><span>{a.kind} · {formatDate(a.date)}</span><small>{a.note}</small></div></div>)}</div>:<div className="compact-empty">{tx("No recorded milestones yet. Keep learning to unlock the first checkpoint.")}</div>}</section><section className="next-step-card"><div className="next-step-top"><Sparkles size={16}/><span>{tx("UP NEXT")}</span></div><strong>{course.phases[Math.min(course.phases.length-1,Math.floor(student.progress/(100/course.phases.length)))].modules[0]?.name ?? 'Final portfolio review'}</strong><p>{tx("A suggested next step from this demo roadmap.")}</p><button onClick={()=>setTab('roadmap')}>{tx("View learning path")} <ArrowRight size={14}/></button></section></aside></div>}
    {tab==='roadmap'&&<RoadmapView course={course} student={student}/>}
    {tab==='skills'&&<div className="panel profile-section"><div className="panel-heading"><div><h2>{tx("Skills & evidence")}</h2><p>{student.skills.length} demonstrated skills across this learner profile</p></div>{isAdmin&&<button className="btn btn-secondary btn-sm" onClick={()=>setEditing(true)}><Settings2 size={14}/>{tx("Edit skills")}</button>}</div><div className="skill-evidence-grid">{student.skills.map(s=><SkillEvidenceCard key={s.name} item={s}/>)}</div></div>}
    {tab==='portfolio'&&<div className="profile-project-grid">{studentProjects.map(p=><ProjectCard key={p.id} project={p} student={student}/>)}</div>}
    {isAdmin&&editing&&<EditStudentModal student={student} onClose={()=>setEditing(false)} onSave={saveProfile}/>}{isAdmin&&adding&&<AddProjectModal onClose={()=>setAdding(false)} onSave={addProject}/>}
  </>
}

function guessCategory(name:string):SkillEvidence['category'] { if(['React','Unity','React Native'].includes(name))return 'Frameworks';if(['SQL','PostgreSQL','MongoDB'].includes(name))return 'Databases';if(['Figma','Photoshop','Illustrator','After Effects'].includes(name))return 'Design & Creative Tools';if(['Python','JavaScript','TypeScript','C','C++','C#','Bash'].includes(name))return 'Programming Languages';if(['Docker','Linux','CI/CD','Networking'].includes(name))return 'DevOps & Infrastructure';return 'AI & Machine Learning' }
function formatDate(date:string) { return new Date(`${date}T12:00:00`).toLocaleDateString(document.documentElement.lang==='hy'?'hy-AM':'en-US',{month:'short',year:'numeric'}) }

function EditStudentModal({student,onClose,onSave}:{student:Student;onClose:()=>void;onSave:(bio:string,progress:number,status:StudentStatus,skills:string[])=>void}) {
  const [bio,setBio]=useState(student.bio);const [progress,setProgress]=useState(student.progress);const [status,setStatus]=useState<StudentStatus>(student.status);const [skills,setSkills]=useState(student.skills.map(s=>s.name).join(', '))
  return <Modal title="Edit student profile" subtitle="Changes are stored in this browser for the demo." onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave(bio,progress,status,skills.split(',').map(s=>s.trim()).filter(Boolean))}} className="modal-form"><label>{tx("Biography")}<textarea value={bio} onChange={e=>setBio(e.target.value)} rows={3}/></label><label>{tx("Skills")} <span className="field-hint">{tx("Separate skills with commas")}</span><input value={skills} onChange={e=>setSkills(e.target.value)}/></label><div className="form-row"><label>{tx("Roadmap progress")} <div className="range-label"><input type="range" min="0" max="100" value={progress} onChange={e=>setProgress(Number(e.target.value))}/><b>{progress}%</b></div></label><label>{tx("Status")}<select value={status} onChange={e=>setStatus(e.target.value as StudentStatus)}>{['Active','Graduated','Paused','At risk'].map(x=><option key={x} value={x}>{tx(x)}</option>)}</select></label></div><div className="modal-actions"><button type="button" className="btn btn-secondary" onClick={onClose}>{tx("Cancel")}</button><button className="btn btn-primary"><Check size={15}/>{tx("Save changes")}</button></div></form></Modal>
}
function AddProjectModal({onClose,onSave}:{onClose:()=>void;onSave:(title:string,description:string,technologies:string[],category:string)=>void}) {
  const [title,setTitle]=useState('');const [description,setDescription]=useState('');const [technologies,setTechnologies]=useState('');const [category,setCategory]=useState('Web app')
  return <Modal title="Add a project" subtitle="Add a fictional demo project to this student’s portfolio." onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave(title,description,technologies.split(',').map(x=>x.trim()).filter(Boolean),category)}} className="modal-form"><label>{tx("Project title")}<input required value={title} onChange={e=>setTitle(e.target.value)} placeholder="e.g. Learning Progress Dashboard"/></label><label>{tx("Description")}<textarea required value={description} onChange={e=>setDescription(e.target.value)} rows={3} placeholder="What did the student build?"/></label><div className="form-row"><label>{tx("Technologies")} <span className="field-hint">{tx("Comma separated")}</span><input value={technologies} onChange={e=>setTechnologies(e.target.value)} placeholder="React, TypeScript"/></label><label>{tx("Category")}<select value={category} onChange={e=>setCategory(e.target.value)}>{['Web app','AI app','Product design','Game','Infrastructure','Creative AI'].map(x=><option key={x}>{x}</option>)}</select></label></div><div className="modal-actions"><button type="button" className="btn btn-secondary" onClick={onClose}>{tx("Cancel")}</button><button className="btn btn-primary"><Plus size={15}/>{tx("Add project")}</button></div></form></Modal>
}
function Modal({title,subtitle,onClose,children}:{title:string;subtitle:string;onClose:()=>void;children:ReactNode}) { return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="modal"><div className="modal-heading"><div><h2>{title}</h2><p>{subtitle}</p></div><button className="icon-btn" onClick={onClose} aria-label="Close dialog"><X size={19}/></button></div>{children}</section></div> }

function SkillEvidenceRow({item}:{item:SkillEvidence}) { return <div className="skill-evidence-row"><span className="skill-mark"><Sparkles size={14}/></span><div className="skill-name-wrap"><strong>{item.name}</strong><small>{tx(item.category)}</small></div><span className={`proficiency proficiency-${item.proficiency.toLowerCase()}`}>{tx(item.proficiency)}</span><span className="evidence-text">{item.evidence}</span></div> }
function SkillEvidenceCard({item}:{item:SkillEvidence}) { return <div className="skill-evidence-card"><div className="skill-card-title"><span className="skill-mark"><Sparkles size={14}/></span><span><strong>{item.name}</strong><small>{tx(item.category)}</small></span><span className={`proficiency proficiency-${item.proficiency.toLowerCase()}`}>{tx(item.proficiency)}</span></div><div className="evidence-box"><span>{tx("MODULE")}</span><strong>{item.module}</strong><small>{item.evidence}</small></div></div> }

function ProjectArt({project}:{project:Project}) { return <div className={`project-art ${project.art}`}><div className="art-orbit orbit-a"/><div className="art-orbit orbit-b"/><span className="art-symbol">{project.category.includes('design')||project.category==='Branding'?'✦':project.category==='Game'?'◉':project.category==='Infrastructure'?'⌘':project.category==='AI'?'✳':'▧'}</span><div className="art-label">{project.category.toUpperCase()}</div></div> }
function ProjectCard({project,student}:{project:Project;student:Student}) { return <article className="project-card"><ProjectArt project={project}/><div className="project-card-body"><div className="project-card-top"><span className="project-category">{project.category}</span><StatusPill status={project.status}/></div><h3>{project.title}</h3><p>{project.description}</p><div className="inline-chips">{project.technologies.slice(0,3).map(x=><span className="skill-chip" key={x}>{x}</span>)}</div><div className="project-card-foot"><Link to={`/students/${student.id}`} className="project-author"><Avatar student={student} size="sm"/><span>{student.name}<small>{courseName(student.courseId)}</small></span></Link>{project.status==='Completed'?<span className="project-score"><Award size={14}/>{project.score}<small>/100</small></span>:<span className="project-date">{formatDate(project.completedAt)}</span>}</div></div></article> }

function RoadmapView({course,student}:{course:Course;student:Student}) {
  const [expanded,setExpanded]=useState<number[]>(course.phases.map((_,i)=>i))
  const toggle=(i:number)=>setExpanded(expanded.includes(i)?expanded.filter(x=>x!==i):[...expanded,i])
  return <div className="roadmap-view"><div className="roadmap-context-banner"><div className="course-icon" style={{background:`linear-gradient(140deg, ${course.colors[0]}, ${course.colors[1]})`}}>{course.icon}</div><div><strong>{course.title} {tx("Learning roadmap").toLowerCase()}</strong><span>{tx(course.duration)} · {tx(course.publicInfo)} · {tx("Student progress shown for")} {student.name}</span></div><Link className="text-link" to={`/courses/${course.id}`}>{tx("Course details")} <ArrowRight size={14}/></Link></div><div className="info-note"><CircleHelp size={15}/><span>{course.publicInfo==='Verified public details'?tx('Public course outlines are referenced. Summaries, assignments, module completion, and student evidence in this demo are illustrative.') : tx('This roadmap is illustrative demo content. Only course listing details are public; the roadmap, assignments, and learner evidence are not official Academy curriculum.')}</span></div><div className="roadmap-phases">{course.phases.map((p,i)=>{const phaseProgress=Math.max(0,Math.min(100,Math.round((student.progress-i*(100/course.phases.length))/(100/course.phases.length)*100)));const status=phaseProgress>=100?'Completed':phaseProgress>0?'In progress':'Upcoming';return <section className={`roadmap-phase ${expanded.includes(i)?'expanded':''}`} key={p.name}><button className="phase-head" onClick={()=>toggle(i)}><span className={`phase-index ${status==='Completed'?'complete':''}`}>{status==='Completed'?<Check size={15}/>:String(i+1).padStart(2,'0')}</span><span className="phase-title"><strong>{tx(p.name.replace(/^\d+ · /,''))}</strong><small>{p.modules.length} modules · {status}</small></span><span className="phase-progress-wrap"><ProgressBar value={phaseProgress}/><b>{phaseProgress}%</b></span><ChevronDown size={18} className="phase-chevron"/></button>{expanded.includes(i)&&<div className="module-list">{p.modules.map((m,mi)=><div className="module-row" key={m.name}><span className={`module-check ${phaseProgress>=(mi+1)/p.modules.length*100?'checked':''}`}>{phaseProgress>=(mi+1)/p.modules.length*100?<Check size={12}/>:<span/>}</span><div className="module-content"><strong>{m.name}</strong><div className="module-topics">{m.topics.map(t=><span key={t}>{t}</span>)}</div><div className="inline-chips">{m.skills.map(s=><span className="skill-chip" key={s}>{s}</span>)}</div><small className="assignment"><FolderKanban size={12}/>{m.assignment}</small></div><span className="module-state">{tx(phaseProgress>0?'Demo module':'Upcoming')}</span></div>)}</div>}</section>})}</div></div>
}

function CoursesPage() {
  const {students}=useHub(); const [search,setSearch]=useState(''); const filtered=courses.filter(c=>`${c.title} ${c.track} ${c.technologies.join(' ')}`.toLowerCase().includes(search.toLowerCase()))
  return <><PageHeading eyebrow="LEARNING PATHS" title="Courses & roadmaps" description="Explore Academy programs and the skills students are building." actions={<div className="public-source-note"><span className="source-dot"/>{tx("Public program details + clearly marked demo roadmaps")}</div>} /><div className="course-page-search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder={tx("Search courses, technologies, focus areas...")}/><span>{filtered.length} {txCount(filtered.length,"program","programs")}</span></div><div className="courses-grid">{filtered.map(c=><CourseCard key={c.id} course={c} studentCount={students.filter(s=>s.courseId===c.id).length}/>)}</div>{!filtered.length&&<div className="empty-state"><div className="empty-icon"><BookOpen size={22}/></div><h3>{tx("No course found")}</h3><p>{tx("Try another course name, skill, or focus area.")}</p></div>}<div className="source-disclaimer"><ShieldCheck size={16}/><span>{tx("Course names and durations follow the public catalog where available. Roadmap detail is labeled on each program; some pathways use illustrative demo curriculum.")}</span></div></>
}
function CourseCard({course,studentCount}:{course:Course;studentCount:number}) { return <Link to={`/courses/${course.id}`} className="course-card"><div className="course-card-banner" style={{background:`linear-gradient(130deg, ${course.colors[0]}, ${course.colors[1]})`}}><span className="course-card-icon">{course.icon}</span><span className="course-track-pill">{course.track.split(' · ')[0]}</span><div className="course-banner-orbit one"/><div className="course-banner-orbit two"/></div><div className="course-card-body"><div className="course-card-meta"><span><Clock3 size={13}/>{tx(course.duration)}</span><span><Users size={13}/>{studentCount} {txCount(studentCount,"student","students")}</span><span><BookOpen size={13}/>{course.phases.reduce((sum,phase)=>sum+phase.modules.length,0)} {tx("modules")}</span></div><div className="course-card-level"><Sparkles size={12}/><span>{tx("Demo learning level")}</span><b>{tx(course.learningLevel)}</b></div><h3>{course.title}</h3><p>{tx(course.summary)}</p><div className="inline-chips">{course.technologies.slice(0,4).map(x=><span className="skill-chip" key={x}>{x}</span>)}</div><div className="course-card-foot"><span className={`curriculum-tag ${course.publicInfo==='Verified public details'?'verified':''}`}><i/>{tx(course.publicInfo==='Verified public details'?'Public outline referenced':'Illustrative demo roadmap')}</span><span className="course-view">{tx("View roadmap")} <ArrowRight size={14}/></span></div></div></Link> }
function CourseDetail() { const {id=''}=useParams();const course=courses.find(c=>c.id===id);const {students,isAdmin}=useHub();const [expanded,setExpanded]=useState<number[]>([]);if(!course)return <NotFound/>;const related=students.filter(s=>s.courseId===course.id);return <><div className="profile-breadcrumb"><Link className="back-link" to={isAdmin?'/courses':'/students'}><ArrowLeft size={15}/>{tx(isAdmin?"Courses & Roadmaps":"Students")}</Link><ChevronRight size={14}/><span>{course.title}</span></div><section className="course-detail-hero"><div className="course-detail-cover" style={{background:`linear-gradient(130deg, ${course.colors[0]}, ${course.colors[1]})`}}><span>{course.icon}</span><div className="course-banner-orbit one"/><div className="course-banner-orbit two"/></div><div className="course-detail-copy"><div className={`curriculum-tag ${course.publicInfo==='Verified public details'?'verified':''}`}><i/>{tx(course.publicInfo==='Verified public details'?'Public outline referenced':'Illustrative demo roadmap')}</div><h1>{course.title}</h1><p>{tx(course.summary)}</p><div className="course-detail-facts"><span><Clock3 size={15}/>{tx(course.duration)}</span><span><Users size={15}/>{related.length} {txCount(related.length,"fictional demo profile","fictional demo profiles")}</span><span><BookOpen size={15}/>{course.phases.length} {tx("phases")} · {course.phases.reduce((a,p)=>a+p.modules.length,0)} {tx("modules")}</span></div></div></section><section className="panel course-outcomes"><div className="panel-heading"><div><h2>{tx("What Can You Become?")}</h2><p>{tx("Potential learning directions · outcomes are not guaranteed employment qualifications")}</p></div></div><div className="outcome-chips">{course.professionalOutcomes.map(outcome=><span key={outcome}><CheckCircle2 size={14}/>{tx(outcome)}</span>)}</div><div className="capstone-outcome"><FolderKanban size={17}/><span><b>{tx("Final project expectation")}</b><small>{course.phases[course.phases.length-1].modules[course.phases[course.phases.length-1].modules.length-1].assignment}</small></span></div></section><div className="info-note"><CircleHelp size={15}/><span>{course.publicInfo==='Verified public details'?tx('Public course outlines are referenced. Summaries, assignments, module completion, and student evidence in this demo are illustrative.') : tx('This roadmap is illustrative demo content. Only course listing details are public; the roadmap, assignments, and learner evidence are not official Academy curriculum.')}</span></div><div className="course-detail-grid"><div><section className="panel course-objectives"><div className="panel-heading"><div><h2>{tx("Learning objectives")}</h2><p>{tx("Skills and outcomes represented in this demo roadmap")}</p></div></div><div className="objective-list">{course.objectives.map((x,i)=><div key={x}><span>{String(i+1).padStart(2,'0')}</span><strong>{x}</strong></div>)}</div></section><section className="roadmap-section"><div className="panel-heading"><div><h2>{tx("Learning roadmap")}</h2><p>{tx("Phases, modules, skills, and practical assignments")}</p></div><button className="text-link" onClick={()=>setExpanded(expanded.length===course.phases.length?[]:course.phases.map((_,i)=>i))}>{tx(expanded.length===course.phases.length?'Collapse all':'Expand all')}<ChevronDown size={14}/></button></div><div className="roadmap-phases">{course.phases.map((p,i)=><section className={`roadmap-phase ${expanded.includes(i)?'expanded':''}`} key={p.name}><button className="phase-head" onClick={()=>setExpanded(expanded.includes(i)?expanded.filter(x=>x!==i):[...expanded,i])}><span className="phase-index">{String(i+1).padStart(2,'0')}</span><span className="phase-title"><strong>{tx(p.name.replace(/^\d+ · /,''))}</strong><small>{p.modules.length} {tx('modules')} · {p.modules.reduce((a,m)=>a+m.topics.length,0)} {tx('topics')}</small></span><ChevronDown size={18} className="phase-chevron"/></button>{expanded.includes(i)&&<div className="module-list">{p.modules.map(m=><div className="module-row" key={m.name}><span className="module-check"><BookOpen size={12}/></span><div className="module-content"><strong>{m.name}</strong><div className="module-topics">{m.topics.map(t=><span key={t}>{t}</span>)}</div><div className="inline-chips">{m.skills.map(s=><span className="skill-chip" key={s}>{s}</span>)}</div><small className="assignment"><FolderKanban size={12}/>{m.assignment}</small></div></div>)}</div>}</section>)}</div></section></div><aside className="course-detail-side"><section className="panel"><div className="panel-heading"><div><h2>{tx("Key technologies")}</h2><p>{tx("Tools and concepts in this path")}</p></div></div><div className="tech-cloud">{course.technologies.map(x=><span className="skill-chip" key={x}>{x}</span>)}</div></section><section className="panel related-students"><div className="panel-heading"><div><h2>{tx("Related students")}</h2><p>{related.length} {txCount(related.length,"fictional demo profile","fictional demo profiles")}</p></div><Link className="text-link" to={`/students?course=${course.id}`}>{tx("View all")} <ArrowRight size={13}/></Link></div>{related.slice(0,4).map(s=><Link to={`/students/${s.id}`} className="related-student" key={s.id}><Avatar student={s} size="sm"/><span><strong>{s.name}</strong><small>{s.progress}% progress · {s.level}</small></span><ChevronRight size={15}/></Link>)}</section></aside></div>{isAdmin&&<CourseTopStudents courseId={course.id} useHub={useHub} Avatar={Avatar} t={tx}/>}</> }

function SkillsPage() { const {students}=useHub();const [searchParams]=useSearchParams();const requestedSkill=searchParams.get('skill');const [selected,setSelected]=useState(requestedSkill&&skillNamesFor(students).includes(requestedSkill)?requestedSkill:'Python');const [category,setCategory]=useState('all');const counts=skillNamesFor(students).map(name=>({name,students:students.filter(s=>s.skills.some(x=>x.name===name)).length,advanced:students.filter(s=>s.skills.some(x=>x.name===name&&x.proficiency==='Advanced')).length,category:students.find(s=>s.skills.some(x=>x.name===name))?.skills.find(x=>x.name===name)?.category??''})).sort((a,b)=>b.students-a.students);const list=counts.filter(x=>category==='all'||x.category===category);const selectedStudents=students.filter(s=>s.skills.some(x=>x.name===selected)).map(s=>({student:s,skill:s.skills.find(x=>x.name===selected)!}));return <><PageHeading eyebrow="SKILL INTELLIGENCE" title="Skills explorer" description="Explore the capabilities represented across the demo cohort." actions={<div className="skill-total"><Sparkles size={16}/><strong>{skillNamesFor(students).length}</strong><span>{tx("distinct skills in dataset")}</span></div>} /><section className="skill-hero-panel"><div><div className="eyebrow">{tx("DISCOVER BY TECHNOLOGY")}</div><h2>{tx("What can your learners do?")}</h2><p>{tx("Select a skill to see proficiency levels and linked project evidence.")}</p></div><label className="skill-select"><Search size={17}/><select value={selected} onChange={e=>setSelected(e.target.value)}>{skillNamesFor(students).map(x=><option key={x}>{x}</option>)}</select><ChevronDown size={15}/></label></section><div className="skill-analytics-grid"><section className="panel skill-popular-panel"><div className="panel-heading"><div><h2>{tx("Most common skills")}</h2><p>{tx("Skills with the widest representation")}</p></div><select value={category} onChange={e=>setCategory(e.target.value)} className="compact-select"><option value="all">{tx("All categories")}</option>{skillCategories.map(x=><option key={x}>{x}</option>)}</select></div><div className="skill-ranking">{list.slice(0,9).map((x,i)=><button className={`skill-rank-row ${selected===x.name?'selected':''}`} key={x.name} onClick={()=>setSelected(x.name)}><span className="rank-number">{String(i+1).padStart(2,'0')}</span><span className="skill-rank-copy"><strong>{x.name}</strong><small>{x.category}</small></span><div className="skill-count-bar"><span style={{width:`${Math.max(7,x.students/Math.max(...list.map(a=>a.students),1)*100)}%`}}/></div><span className="skill-count">{x.students}<small> {tx("learners")}</small></span></button>)}</div></section><section className="panel selected-skill-panel"><div className="panel-heading"><div><h2>{selected}</h2><p>{tx("Students and evidence for selected skill")}</p></div><span className="selected-count">{selectedStudents.length}</span></div>{selectedStudents.length?<div className="skill-student-list">{selectedStudents.map(({student,skill})=><Link to={`/students/${student.id}`} className="skill-student-row" key={student.id}><Avatar student={student} size="sm"/><span className="skill-student-copy"><strong>{student.name}</strong><small>{courseName(student.courseId)}</small></span><span className={`proficiency proficiency-${skill.proficiency.toLowerCase()}`}>{skill.proficiency}</span><span className="skill-proof"><small>{skill.module}</small><b>{skill.evidence}</b></span><ArrowRight size={15}/></Link>)}</div>:<div className="compact-empty">No learners are associated with this skill yet.</div>}<div className="selected-skill-footer"><span>{tx("Proficiency and evidence are fictional demo records.")}</span><Link to={`/students?skill=${encodeURIComponent(selected)}`}>{tx("Open in directory")} <ArrowRight size={13}/></Link></div></section></div><div className="skill-bottom-grid"><section className="panel"><div className="panel-heading"><div><h2>{tx("Advanced skill signals")}</h2><p>{tx("Skills with advanced proficiency records")}</p></div></div><div className="advanced-skill-list">{counts.filter(x=>x.advanced>0).sort((a,b)=>b.advanced-a.advanced).slice(0,8).map(x=><button key={x.name} onClick={()=>setSelected(x.name)} className="advanced-skill-item"><span className="advanced-icon"><Flame size={14}/></span><span><strong>{x.name}</strong><small>{x.advanced} advanced demo {x.advanced===1?'profile':'profiles'}</small></span><ArrowRight size={14}/></button>)}</div></section><section className="panel category-panel"><div className="panel-heading"><div><h2>{tx("Skills by category")}</h2><p>{tx("Coverage across technical disciplines")}</p></div></div><div className="category-list">{skillCategories.map(cat=>{const n=skillNamesFor(students).filter(skillName=>students.some(s=>s.skills.some(sk=>sk.name===skillName&&sk.category===cat))).length;return <div key={cat}><span>{cat}</span><div><i style={{width:`${n/Math.max(1,skillNamesFor(students).length)*100}%`}}/></div><b>{n}</b></div>})}</div></section></div></>}

function ProjectsPage() {
  const { students, projects, roleMode } = useHub()
  const [search, setSearch] = useState('')
  const [category, setCategory] = useState('all')
  const [status, setStatus] = useState('all')
  const student = demoStudent(students)
  const visibleProjects = roleMode !== 'student' ? projects : projects.filter(project => project.studentId === student.id)
  const categories = Array.from(new Set(visibleProjects.map(project => project.category))).sort()
  const filtered = visibleProjects.filter(project => {
    const owner = students.find(item => item.id === project.studentId)
    if (!owner) return false
    return (!search || `${project.title} ${project.description} ${project.technologies.join(' ')} ${owner.name}`.toLowerCase().includes(search.toLowerCase())) && (category === 'all' || project.category === category) && (status === 'all' || project.status === status)
  }).sort((a, b) => b.completedAt.localeCompare(a.completedAt))
  const clear = () => { setSearch(''); setCategory('all'); setStatus('all') }
  return <>
    <PageHeading eyebrow="STUDENT WORK" title={roleMode !== 'student' ? 'Projects gallery' : 'My projects'} description={roleMode !== 'student' ? 'Browse the work students have built across creative and technical paths.' : 'Explore your own portfolio work across your learning path.'} actions={<span className="project-total"><FolderKanban size={16}/>{filtered.length} {tx('projects')}</span>} />
    <div className="project-filters"><label className="project-search"><Search size={17}/><input value={search} onChange={event => setSearch(event.target.value)} placeholder={tx(roleMode !== 'student' ? 'Search projects, students, technologies...' : 'Search your projects and technologies...')}/></label><label><Filter size={15}/><select value={category} onChange={event => setCategory(event.target.value)}><option value="all">{tx('All categories')}</option>{categories.map(value => <option key={value}>{value}</option>)}</select></label><label><CheckCircle2 size={15}/><select value={status} onChange={event => setStatus(event.target.value)}><option value="all">{tx('Any status')}</option>{['Completed', 'In review', 'In progress'].map(value => <option key={value} value={value}>{tx(value)}</option>)}</select></label><button className="clear-filters" onClick={clear} disabled={!search && category === 'all' && status === 'all'}>{tx('Clear')}</button></div>
    {filtered.length ? <div className="project-gallery">{filtered.map(project => { const owner = students.find(item => item.id === project.studentId); return owner ? <ProjectCard key={project.id} project={project} student={owner}/> : null })}</div> : <div className="empty-state"><div className="empty-icon"><FolderKanban size={22}/></div><h3>{tx('No projects found')}</h3><p>{tx(roleMode !== 'student' ? 'Adjust your search or category filters to explore the gallery.' : 'Try a different search or filter to find one of your projects.')}</p><button className="btn btn-secondary" onClick={clear}>{tx('Clear filters')}</button></div>}
  </>
}

const presets = [
  {id:'python-ml',name:'Python + Machine Learning',description:'AI learners with practical model-building experience',skills:['Python','Machine Learning'],course:'all',minProjects:2,minLevel:'Intermediate',progress:0,portfolio:0,readiness:0},
  {id:'frontend-react',name:'Frontend + React',description:'Application builders with modern UI implementation skills',skills:['React','TypeScript'],course:'all',minProjects:2,minLevel:'Developing',progress:0,portfolio:0,readiness:0},
  {id:'linux-network',name:'Linux + Networking + DevOps',description:'Systems learners with infrastructure practice',skills:['Linux','Networking','DevOps'],course:'all',minProjects:2,minLevel:'Developing',progress:0,portfolio:0,readiness:0},
]
function TalentPage() {
  const {students,projects,shortlistedIds,toggleShortlist}=useHub();const [selectedPreset,setSelectedPreset]=useState('python-ml');const [requiredSkills,setRequiredSkills]=useState<string[]>(presets[0].skills);const [skillToAdd,setSkillToAdd]=useState('');const [course,setCourse]=useState('all');const [minLevel,setMinLevel]=useState<Proficiency>('Developing');const [minProjects,setMinProjects]=useState(2);const [minProgress,setMinProgress]=useState(0);const [minPortfolio,setMinPortfolio]=useState(0);const [minReadiness,setMinReadiness]=useState(0);const [showShortlist,setShowShortlist]=useState(false)
  const evaluated=students.map(student=>({student,matchingSkills:student.skills.filter(s=>requiredSkills.includes(s.name)),projectMatches:projects.filter(p=>p.studentId===student.id&&p.status==='Completed'&&(!requiredSkills.length||p.technologies.some(t=>requiredSkills.includes(t)))),score:Math.min(99,Math.round((student.skills.filter(s=>requiredSkills.includes(s.name)).length/Math.max(requiredSkills.length,1))*50+readinessScore(student)*.25+Math.min(25,projectCount(student.id,projects)*7)))}))
  const matches=evaluated.filter(({student})=>requiredSkills.every(skill=>student.skills.some(s=>s.name===skill&&levelOrder[s.proficiency]>=levelOrder[minLevel]))&&(course==='all'||student.courseId===course)&&projectCount(student.id,projects)>=minProjects&&student.progress>=minProgress&&student.readiness.portfolio>=minPortfolio&&readinessScore(student)>=minReadiness).sort((a,b)=>b.score-a.score)
  const visibleMatches=showShortlist?evaluated.filter(row=>shortlistedIds.includes(row.student.id)).map(row=>({...row,matchingSkills:row.student.skills.slice(0,4),projectMatches:projects.filter(project=>project.studentId===row.student.id&&project.status==='Completed')})).sort((a,b)=>b.score-a.score):matches
  const loadPreset=(id:string)=>{const item=presets.find(p=>p.id===id)!;setSelectedPreset(id);setRequiredSkills(item.skills);setCourse(item.course);setMinLevel(item.minLevel as Proficiency);setMinProjects(item.minProjects);setMinProgress(item.progress);setMinPortfolio(item.portfolio);setMinReadiness(item.readiness)}
  const addSkill=()=>{if(skillToAdd&&!requiredSkills.includes(skillToAdd)){setRequiredSkills([...requiredSkills,skillToAdd]);setSelectedPreset('custom')}setSkillToAdd('')}
  const clear=()=>{setSelectedPreset('custom');setRequiredSkills([]);setCourse('all');setMinLevel('Beginner');setMinProjects(0);setMinProgress(0);setMinPortfolio(0);setMinReadiness(0)}
  return <><PageHeading eyebrow="TALENT DISCOVERY" title="Find the right potential" description="Combine demonstrated skills, project evidence, and learning signals to discover learners." actions={<div className="demo-match-note"><ShieldCheck size={15}/><span>{tx("Demo matching indicator")}<br/><small>{tx("Not a hiring recommendation")}</small></span></div>} /><div className="talent-layout"><section className="talent-filters"><div className="talent-filter-head"><div className="filter-heading-icon"><Target size={18}/></div><div><h2>{tx("Build a search")}</h2><p>{tx("Combine criteria to narrow the cohort.")}</p></div><button className="icon-btn" title={tx("Clear criteria")} onClick={clear}><RotateCcw size={15}/></button></div><div className="preset-label">{tx("START WITH AN EXAMPLE")}</div><div className="preset-list">{presets.map(p=><button key={p.id} className={`preset-card ${selectedPreset===p.id?'selected':''}`} onClick={()=>loadPreset(p.id)}><span className="preset-check">{selectedPreset===p.id&&<Check size={12}/>}</span><span><strong>{tx(p.name)}</strong><small>{tx(p.description)}</small></span><ArrowRight size={14}/></button>)}</div><div className="filter-divider"/><label className="criteria-label">{tx("Required skills")} <small>{tx("Match all")}</small></label><div className="required-skill-chips">{requiredSkills.map(x=><button key={x} onClick={()=>{setRequiredSkills(requiredSkills.filter(n=>n!==x));setSelectedPreset('custom')}}>{x}<X size={12}/></button>)}{!requiredSkills.length&&<span className="field-hint">{tx("No skill requirement")}</span>}</div><div className="add-skill-row"><select value={skillToAdd} onChange={e=>setSkillToAdd(e.target.value)}><option value="">{tx("Add a skill…")}</option>{skillNamesFor(students).filter(x=>!requiredSkills.includes(x)).map(x=><option key={x}>{x}</option>)}</select><button onClick={addSkill} disabled={!skillToAdd}><Plus size={15}/>{tx("Add")}</button></div><label className="criteria-label">{tx("Learning path")}</label><select className="wide-select" value={course} onChange={e=>{setCourse(e.target.value);setSelectedPreset('custom')}}><option value="all">{tx("Any learning path")}</option>{courses.map(c=><option value={c.id} key={c.id}>{c.title}</option>)}</select><label className="criteria-label">{tx("Minimum proficiency")}</label><select className="wide-select" value={minLevel} onChange={e=>{setMinLevel(e.target.value as Proficiency);setSelectedPreset('custom')}}>{(["Beginner","Developing","Intermediate","Advanced"] as const).map(x=><option key={x} value={x}>{tx(x)}</option>)}</select><div className="criteria-range"><label>{tx("Completed projects")} <b>{minProjects}+</b></label><input type="range" min="0" max="6" value={minProjects} onChange={e=>{setMinProjects(Number(e.target.value));setSelectedPreset('custom')}}/></div><div className="criteria-range"><label>{tx("Learning progress")} <b>{minProgress}%+</b></label><input type="range" min="0" max="100" step="10" value={minProgress} onChange={e=>{setMinProgress(Number(e.target.value));setSelectedPreset('custom')}}/></div><div className="criteria-range"><label>{tx("Portfolio completeness")} <b>{minPortfolio}%+</b></label><input type="range" min="0" max="100" step="10" value={minPortfolio} onChange={e=>{setMinPortfolio(Number(e.target.value));setSelectedPreset('custom')}}/></div><div className="criteria-range"><label>{tx("Demo readiness")} <b>{minReadiness}%+</b></label><input type="range" min="0" max="100" step="10" value={minReadiness} onChange={e=>{setMinReadiness(Number(e.target.value));setSelectedPreset('custom')}}/></div><button className="clear-builder" onClick={clear}>{tx("Clear all criteria")}</button></section>
    <section className="talent-results"><div className="talent-results-head"><div><div className="talent-view-tabs"><button className={!showShortlist?'active':''} onClick={()=>setShowShortlist(false)}>{tx('Matching results')} <b>{matches.length}</b></button><button className={showShortlist?'active':''} onClick={()=>setShowShortlist(true)}>{tx('Shortlist')} <b>{shortlistedIds.length}</b></button></div><div className="eyebrow">{tx(showShortlist?"SAVED LEARNERS":"MATCHING LEARNERS")}</div><h2>{visibleMatches.length} <span>{txCount(visibleMatches.length,'student found','students found')}</span></h2><p>{showShortlist?tx('Profiles saved for organization review.'):requiredSkills.length?<>{tx("Every student matches")} <b>{requiredSkills.join(' + ')}</b> {tx("at")} <b>{tx(minLevel)}</b> {tx("level or above.")}</>:<>{tx('Showing students that meet your project and readiness criteria.')}</>}</p></div><button className="btn btn-secondary btn-sm" onClick={()=>window.print()}><Download size={14}/>{tx("Export matches")}</button></div><div className="criteria-summary">{requiredSkills.length?requiredSkills.map(x=><span key={x}><Check size={11}/>{x}</span>):<span>{tx('Any skill')}</span>}<span><FolderKanban size={12}/>{minProjects}+ {tx('completed projects')}</span>{course!=='all'&&<span><BookOpen size={12}/>{courseName(course)}</span>}</div>{visibleMatches.length?<div className="talent-match-list">{visibleMatches.map(({student,matchingSkills,projectMatches,score})=><TalentMatchCard key={student.id} student={student} skills={matchingSkills} projects={projectMatches} score={score} completedCount={projectCount(student.id,projects)} shortlisted={shortlistedIds.includes(student.id)} onToggleShortlist={()=>toggleShortlist(student.id)}/>)}</div>:<div className="talent-empty"><div className="empty-icon"><Search size={22}/></div><h3>{tx(showShortlist?"Your shortlist is empty":"No exact matches yet")}</h3><p>{tx(showShortlist?"Save promising learners from the matching results to review them here.":"Try lowering the proficiency or project threshold, or remove one required skill.")}</p><button className="btn btn-secondary" onClick={()=>showShortlist?setShowShortlist(false):clear()}>{tx(showShortlist?"Browse matches":"Reset criteria")}</button></div>}<div className="matching-footnote"><CircleHelp size={14}/>{tx("Demo match indicator ranks criteria coverage and project evidence. It is not a real hiring recommendation.")}</div></section></div></>
}
function TalentMatchCard({student,skills,projects,score,completedCount,shortlisted,onToggleShortlist}:{student:Student;skills:SkillEvidence[];projects:Project[];score:number;completedCount:number;shortlisted:boolean;onToggleShortlist:()=>void}) {return <article className="talent-match-card"><div className="match-person"><Avatar student={student} size="lg"/><div><Link to={`/students/${student.id}`}><strong>{student.name}</strong><ArrowRight size={14}/></Link><span><i style={{background:courseFor(student.courseId).colors[0]}}/>{courseName(student.courseId)} · {tx(student.level)}</span><small>{tx(student.stage)} · {student.progress}% {tx("progress")}</small></div><div className="match-indicator"><div className="match-score-ring" style={{'--score':`${score*3.6}deg`} as React.CSSProperties}><strong>{score}</strong></div><span>{tx('DEMO MATCH')}</span></div></div><div className="match-evidence"><div className="match-evidence-col"><span className="evidence-heading"><Sparkles size={13}/>{tx("MATCHING SKILLS")}</span><div className="match-skill-list">{skills.map(s=><div className="match-skill" key={s.name}><span><strong>{s.name}</strong><small>{s.evidence}</small></span><b className={`proficiency proficiency-${s.proficiency.toLowerCase()}`}>{tx(s.proficiency)}</b></div>)}</div></div><div className="match-evidence-col"><span className="evidence-heading"><FolderKanban size={13}/>{tx("RELATED PROJECT EVIDENCE")}</span>{projects.length?projects.slice(0,2).map(p=><div className="match-project" key={p.id}><strong>{p.title}</strong><span>{p.technologies.filter(t=>skills.some(s=>s.name===t)).join(' · ')||p.category} · score {p.score}</span></div>):<span className="field-hint">{tx('No project used a required skill directly.')}</span>}</div></div><div className="match-card-footer"><StatusPill status={student.status}/><span><FolderKanban size={13}/>{completedCount} {tx('completed projects')}</span><span><Target size={13}/>{student.readiness.portfolio}% {tx('portfolio coverage')}</span><Link to={`/students/${student.id}`}>{tx("View profile")} <ArrowRight size={13}/></Link><button type="button" className={`shortlist-button ${shortlisted?'saved':''}`} aria-pressed={shortlisted} onClick={onToggleShortlist}><Bookmark size={14}/>{tx(shortlisted?'Remove from shortlist':'Add to shortlist')}</button></div></article>}

function AnalyticsPage() {const {students,projects}=useHub();const completed=projects.filter(p=>p.status==='Completed').length;const completionRate=Math.round(completed/Math.max(projects.length,1)*100);const progressBuckets=[{name:'0–24%',value:students.filter(s=>s.progress<25).length},{name:'25–49%',value:students.filter(s=>s.progress>=25&&s.progress<50).length},{name:'50–74%',value:students.filter(s=>s.progress>=50&&s.progress<75).length},{name:'75–99%',value:students.filter(s=>s.progress>=75&&s.progress<100).length},{name:'Complete',value:students.filter(s=>s.progress===100).length}];const skillData=skillNamesFor(students).map(name=>({name,count:students.filter(s=>s.skills.some(x=>x.name===name)).length})).sort((a,b)=>b.count-a.count).slice(0,8);const courseData=courses.map(c=>({name:c.title,students:students.filter(s=>s.courseId===c.id).length,avg:Math.round(students.filter(s=>s.courseId===c.id).reduce((a,s)=>a+s.progress,0)/Math.max(1,students.filter(s=>s.courseId===c.id).length))}));const activity=[{m:'Jun',projects:projects.filter(p=>p.completedAt.startsWith('2026-06')).length},{m:'Jul',projects:projects.filter(p=>p.completedAt.startsWith('2026-07')).length},{m:'Aug',projects:projects.filter(p=>p.completedAt.startsWith('2026-08')).length},{m:'Sep',projects:projects.filter(p=>p.completedAt.startsWith('2026-09')).length},{m:'Oct',projects:projects.filter(p=>p.completedAt.startsWith('2026-10')).length},{m:'Nov',projects:projects.filter(p=>p.completedAt.startsWith('2026-11')).length}];return <><PageHeading eyebrow="COHORT INSIGHTS" title="Analytics" description="Track enrollment, learning progress, skills, and project outcomes." actions={<div className="analytics-period"><span className="period-dot"/>{tx("All demo records")} <ChevronDown size={14}/></div>} /><section className="metric-grid metric-grid-4"><MetricCard label="Students enrolled" value={students.length} icon={Users} tone="violet" foot="Fictional demo cohort"/><MetricCard label="Learning paths" value={courses.length} icon={BookOpen} tone="blue" foot="Public program catalog inspired"/><MetricCard label="Project completion" value={`${completionRate}%`} icon={CheckCircle2} tone="green" foot={`${completed} completed projects`}/><MetricCard label="Avg. demo readiness" value={`${Math.round(students.reduce((a,s)=>a+readinessScore(s),0)/Math.max(1,students.length))}%`} icon={Target} tone="orange" foot="Illustrative evaluation only"/></section><div className="analytics-grid"><section className="panel analytics-progress"><div className="panel-heading"><div><h2>{tx("Learning progress distribution")}</h2><p>{tx("Share of students by roadmap completion band")}</p></div></div><div className="analytics-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={progressBuckets} margin={{top:12,right:15,left:-15,bottom:0}}><CartesianGrid vertical={false} stroke="#efedf2"/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill:'#8e8999',fontSize:11}}/><YAxis allowDecimals={false} axisLine={false} tickLine={false} tick={{fill:'#8e8999',fontSize:11}}/><Tooltip contentStyle={{border:'1px solid #eeeaf3',borderRadius:12}}/><Bar dataKey="value" name="Students" fill="#8060df" radius={[6,6,0,0]} barSize={32}/></BarChart></ResponsiveContainer></div></section><section className="panel analytics-activity"><div className="panel-heading"><div><h2>{tx("Project activity")}</h2><p>{tx("Completed demo work by month")}</p></div><span className="chart-pill">2026</span></div><div className="analytics-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={activity} margin={{top:12,right:14,left:-15,bottom:0}}><defs><linearGradient id="activityFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#9075e6" stopOpacity={0.24}/><stop offset="100%" stopColor="#9075e6" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="#efedf2"/><XAxis dataKey="m" axisLine={false} tickLine={false} tick={{fill:'#8e8999',fontSize:11}}/><YAxis allowDecimals={false} axisLine={false} tickLine={false} tick={{fill:'#8e8999',fontSize:11}}/><Tooltip contentStyle={{border:'1px solid #eeeaf3',borderRadius:12}}/><Area type="monotone" dataKey="projects" name="Projects" stroke="#8060df" strokeWidth={2.5} fill="url(#activityFill)"/></AreaChart></ResponsiveContainer></div></section><section className="panel analytics-courses"><div className="panel-heading"><div><h2>{tx("Course popularity & progress")}</h2><p>{tx("Enrollment and average learner progress by path")}</p></div></div><div className="analytics-course-list">{courseData.map(c=><div key={c.name}><span>{c.name}</span><div className="course-enrollment-bar"><i style={{width:`${c.students/students.length*100*8}%`}}/></div><b>{c.students}</b><span className="avg-progress-pill">{c.avg}% avg</span></div>)}</div></section><section className="panel analytics-skills"><div className="panel-heading"><div><h2>{tx("Top skill coverage")}</h2><p>{tx("Students with each skill in their profile")}</p></div><Link className="text-link" to="/skills">Explore skills <ArrowRight size={13}/></Link></div><div className="analytics-skill-list">{skillData.map((x,i)=><div key={x.name}><span className="analytics-skill-rank">{String(i+1).padStart(2,'0')}</span><strong>{x.name}</strong><div><i style={{width:`${x.count/students.length*100}%`}}/></div><b>{x.count}</b></div>)}</div></section></div><p className="analytics-footnote"><ShieldCheck size={14}/>{tx("All visualizations are calculated from the same editable fictional demo dataset.")}</p></>}

function NotFound() {return <div className="empty-state not-found"><div className="empty-icon"><CircleHelp size={22}/></div><h3>We couldn’t find that page</h3><p>The page may have moved or the profile may not exist in this demo dataset.</p><Link className="btn btn-primary" to="/">Back to overview</Link></div>}

export default App
